soup = BeautifulSoup(html, "html.parser")

products = []

# ----------------------------------------
# Find all products
# ----------------------------------------
all_products = soup.select("div.product-single")

print("Found:", len(all_products), "products")

for product in all_products:

    # ----------------------------------------
    # Basic attributes
    # ----------------------------------------
    product_id = (
        product.get("data-id", "")
        .replace("&quot;", "")
        .replace('"', "")
        .strip()
    )

    product_type = product.get("data-type", "").strip()

    product_name = product.get("data-name", "").strip()

    # ----------------------------------------
    # Logo
    # ----------------------------------------
    logo_tag = product.select_one(".logo img")

    logo_url = None

    if logo_tag and logo_tag.has_attr("src"):
        logo_url = logo_tag["src"]

    # ----------------------------------------
    # Active ingredients
    # ----------------------------------------
    ai_tag = product.select_one(".ai p")

    active_ingredients = ""

    if ai_tag:
        active_ingredients = ai_tag.get_text(
            " ",
            strip=True
        )

        active_ingredients = re.sub(
            r"^Active Ingredients:\s*",
            "",
            active_ingredients
        )

    # ----------------------------------------
    # Description
    # ----------------------------------------
    desc_tag = product.select_one(".desc p")

    description = ""

    if desc_tag:
        description = desc_tag.get_text(
            " ",
            strip=True
        )

        description = re.sub(
            r"^Product Description:\s*",
            "",
            description
        )

    # ----------------------------------------
    # Resistance Management
    # ----------------------------------------
    rm_tag = product.select_one(".rm p")

    resistance_management = None

    if rm_tag:

        resistance_management = rm_tag.get_text(
            " ",
            strip=True
        )

        resistance_management = re.sub(
            r"^Resistance Management:\s*",
            "",
            resistance_management
        )

        if resistance_management.lower() == "null":
            resistance_management = None

    # ----------------------------------------
    # EPA Number
    # ----------------------------------------
    epa_tag = product.select_one(".epan p")

    epa_number = None

    if epa_tag:
        epa_number = epa_tag.get_text(
            " ",
            strip=True
        )

        epa_number = re.sub(
            r"^EPA Number:\s*",
            "",
            epa_number
        )

    # ----------------------------------------
    # Product URL
    # ----------------------------------------
    link_tag = product.select_one("a.btn-pr")

    product_url = None

    if link_tag and link_tag.has_attr("href"):

        product_url = (
            "https://www.syngenta-us.com"
            + link_tag["href"]
        )

    # ----------------------------------------
    # Featured
    # ----------------------------------------
    featured = bool(
        product.select_one(".featured-flag")
    )

    # ----------------------------------------
    # Build object
    # ----------------------------------------
    product_data = {
        "id": product_id,
        "name": product_name,
        "type": product_type,
        "active_ingredients": active_ingredients,
        "description": description,
        "resistance_management": resistance_management,
        "epa_number": epa_number,
        "logo_url": logo_url,
        "product_url": product_url,
        "featured": featured
    }

    products.append(product_data)

# ----------------------------------------
# Save JSON
# ----------------------------------------
with open(
    "products.json",
    "w",
    encoding="utf-8"
) as f:

    json.dump(
        products,
        f,
        indent=2,
        ensure_ascii=False
    )

print("Scraped:", len(products), "products")

# Preview first 3
print(
    json.dumps(
        products[:3],
        indent=2,
        ensure_ascii=False
    )
)